import React, { useState } from "react";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";

const App = () => {
  const [activePage, setActivePage] = useState("chat");

  // 🔥 Store chat messages globally so they don’t disappear when switching tabs
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState(""); // Store last searched query

  return (
    <div className="app-container">
      <Navbar setActivePage={setActivePage} />

      <div className="content">
        {activePage === "chat" && (
          <ChatBox 
            messages={messages} 
            setMessages={setMessages} 
            setLatestQuery={setLatestQuery} 
          />
        )}

        {activePage === "youtube" && <YouTube query={latestQuery} />}
        {activePage === "wikipedia" && <Wikipedia query={latestQuery} />}
        {activePage === "test" && <Test />}
      </div>

      <footer className="footer">
        <p>&copy; 2025 PAT | @Indrajit002</p>
      </footer>
    </div>
  );
};

export default App;
